        <div className="flex items-center gap-2 pb-3 border-b border-border-medium text-xs font-mono font-bold uppercase tracking-wider text-zinc-500">
          <Folder className="h-4.5 w-4.5 text-brand-orange" />
          <span>System File Outline</span>
        </div>

        <div className="flex-grow space-y-1.5 overflow-y-auto max-h-[480px] lg:max-h-[600px] pr-1">
          {GQR_CODE_FILES.map(file => (
            <button
              key={file.path}
              onClick={() => {
                setSelectedFile(file);
                setCopied(false);
