              <div className="space-y-2 max-h-[140px] overflow-y-auto">
                {selectedInd.inputs.length > 0 ? (
                  selectedInd.inputs.map((inp, idx) => (
                    <div key={idx} className="flex justify-between items-center text-xs p-2 rounded bg-card-dark border border-border-dark">
                      <span className="font-semibold text-zinc-400 font-sans">{inp.name}</span>
                      <div className="flex gap-2 font-mono">
                        <span className="text-zinc-500 bg-zinc-950/50 px-1.5 py-0.5 rounded text-[10px] border border-border-dark">
                          {inp.type}
                        </span>
                        <span className="text-brand-orange font-medium">{inp.defaultVal}</span>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="text-center py-6 text-zinc-500 text-xs font-mono">
                    No custom user inputs. Self-calculating.
                  </div>
                )}
              </div>
            </div>

            {/* Alerts Channel */}
            <div className="bg-[#050505]/45 border border-border-dark rounded-xl p-4">
              <div className="flex items-center gap-2 mb-3 text-xs font-mono font-bold uppercase tracking-wider text-zinc-400">
                <BellRing className="h-4 w-4 text-brand-orange" />
                <span>Integrated Alert Conditions</span>
              </div>
              <div className="space-y-2 max-h-[140px] overflow-y-auto">
                {selectedInd.alerts.length > 0 ? (
                  selectedInd.alerts.map((al, idx) => (
                    <div key={idx} className="flex items-center gap-2.5 text-xs p-2 rounded bg-card-dark border border-border-dark">
                      <span className="h-1.5 w-1.5 rounded-full bg-brand-orange animate-pulse"></span>
                      <span className="font-mono text-zinc-300">{al}</span>
                    </div>
                  ))
                ) : (
                  <div className="text-center py-6 text-zinc-500 text-xs font-mono">
                    No explicit alert conditions formulated inside indicator.
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Interactive Code Editor Representation */}
          <div className="flex flex-col rounded-xl overflow-hidden border border-border-dark">
            {/* Tab header */}
            <div className="bg-card-dark px-4 py-2.5 flex items-center justify-between border-b border-border-dark select-none">
              <div className="flex items-center gap-2">
                <Terminal className="h-4 w-4 text-zinc-500" />
                <span className="text-xs font-mono text-zinc-400">{selectedInd.id}.pine</span>
              </div>
              <div className="flex items-center gap-1.5 text-[10px] text-zinc-500 font-mono bg-zinc-950 px-2 py-0.5 rounded border border-border-dark">
                <span>UTF-8</span>
                <span className="h-2 w-px bg-[#1a1a1a]"></span>
                <span>Pine v5</span>
              </div>
            </div>

            {/* Code lines */}
            <div className="bg-[#050505] p-4 font-mono text-[11px] sm:text-xs text-zinc-400 leading-relaxed overflow-x-auto max-h-[360px] overflow-y-auto scrollbar-thin">
              <table className="w-full border-collapse">
                <tbody>
                  {selectedInd.code.split('\n').map((line, idx) => {
                    // Primitive syntax highlights simulation
                    let styleClass = 'text-zinc-400';
                    if (line.trim().startsWith('//') || line.trim().startsWith('/*') || line.trim().startsWith('*')) {
                      styleClass = 'text-zinc-500 italic';
                    } else if (line.trim().startsWith('var ') || line.trim().startsWith('if ') || line.trim().startsWith('else') || line.trim().startsWith('for ') || line.trim().startsWith('while ')) {
                      styleClass = 'text-brand-orange';
                    } else if (line.trim().includes('indicator(') || line.trim().includes('input.')) {
                      styleClass = 'text-[#f27d26]/90';
                    } else if (line.includes('color=')) {
                      styleClass = 'text-zinc-200';
                    }

                    return (
                      <tr key={idx} className="hover:bg-zinc-900/40">
                        <td className="w-10 pr-3 text-right text-zinc-600 font-mono text-[10px] border-r border-[#151515] select-none">
                          {idx + 1}
                        </td>
                        <td className={`pl-4 font-mono break-all whitespace-pre ${styleClass}`}>
                          {line}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useRef } from 'react';

declare global {
  interface Window {
    TradingView: any;
  }
}

interface TradingViewChartProps {
  symbol: string; // 'XAUUSD' | 'EURUSD' | 'DXY'
  height?: number | string;
}

export default function TradingViewChart({ symbol, height = 450 }: TradingViewChartProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  // Map internal symbols to official TradingView symbols
  const getTradingViewSymbol = (sym: string): string => {
    switch (sym) {
      case 'XAUUSD':
        return 'OANDA:XAUUSD';
      case 'EURUSD':
        return 'FX:EURUSD';
      case 'DXY':
        return 'CAPITALCOM:DXY';
      default:
        return 'OANDA:XAUUSD';
    }
  };

  useEffect(() => {
    const containerId = 'tradingview_advanced_chart';

    // Clear legacy elements before mounting a new widget to avoid duplicates
    if (containerRef.current) {
      containerRef.current.innerHTML = `<div id="${containerId}" style="height: 100%; width: 100%;"></div>`;
    }

    const loadWidget = () => {
      if (window.TradingView && containerRef.current) {
        new window.TradingView.widget({
          autosize: true,
          symbol: getTradingViewSymbol(symbol),
          interval: '5',
          timezone: 'Etc/UTC',
          theme: 'dark',
          style: '1',
          locale: 'en',
          enable_publishing: false,
          hide_side_toolbar: false,
          allow_symbol_change: true,
          container_id: containerId,
          backgroundColor: '#050505',
          gridColor: 'rgba(42, 46, 57, 0.2)',
          hide_volume: false,
          studies: [
            'RSI@tv-basicstudies',
            'MASimple@tv-basicstudies' // Moving Average
          ],
          disabled_features: [
            'header_compare',
            'header_screenshot'
          ],
          enabled_features: [
            'dont_show_boolean_study_arguments',
            'use_localstorage_for_settings'
          ],
          loading_screen: {
            backgroundColor: '#050505',
            foregroundColor: '#f27d26'
          }
        });
      }
    };

    // Check if script is already added to document head
    let scriptExists = document.getElementById('tradingview-widget-script');

    if (!scriptExists) {
      const script = document.createElement('script');
      script.id = 'tradingview-widget-script';
      script.src = 'https://s3.tradingview.com/tv.js';
      script.type = 'text/javascript';
      script.async = true;
      script.onload = () => {
        loadWidget();
      };
      document.head.appendChild(script);
    } else {
      // If script is already loaded but we are switching symbol or remounting
      if (window.TradingView) {
        loadWidget();
      } else {
        // In case script is injected but not yet loaded
        const checkInterval = setInterval(() => {
          if (window.TradingView) {
            loadWidget();
            clearInterval(checkInterval);
          }
        }, 100);
        return () => clearInterval(checkInterval);
      }
    }
  }, [symbol]);

  return (
    <div className="w-full bg-[#050505] border border-border-dark rounded-xl overflow-hidden p-1 relative" style={{ height }}>
      {/* Visual background indicator */}
      <div className="absolute top-4 left-4 font-mono text-[9px] text-zinc-600 tracking-wider flex items-center gap-1.5 pointer-events-none z-10 bg-[#050505]/75 px-2 py-1 rounded border border-border-dark">
        <span className="h-1.5 w-1.5 rounded-full bg-brand-orange animate-ping"></span>
        <span>TRADINGVIEW SYSTEM CORE: {symbol} LIVE TERMINAL</span>
      </div>
      <div 
        ref={containerRef} 
        className="w-full h-full rounded-lg overflow-hidden"
        id="tradingview_advanced_chart_container"
      />
    </div>
  );
}
